    '''    queryKey: ["group_court_state", groupId, sessionId],\n    queryFn: async () => {\n      let stateQuery = supabase\n        .from("group_court_state" as any)\n        .select("*")\n        .eq("group_id", groupId!);\n      if (sessionId) stateQuery = stateQuery.eq("session_id", sessionId);\n      const { data, error } = await stateQuery;''',
